import { InputEngineEvent, InputEngineEventName } from "#core/ui/input/input-support.js";
import NavTray from "#core/ui/navigation-tray/model-navigation-tray.js";
import Panel, { AnchorType } from "#core/ui/panel-support.js";
import { MustGetElement } from "#core/ui/utilities/utilities-dom.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";

import content from "#core/ui/shell/mp-additional-content/mp-additional-content.html?raw";
import styles from "#core/ui/shell/mp-additional-content/mp-additional-content.scss?url";

interface MpAdditionalContentOptions {
	title: string;
	type: AdditionalContentType;
	content: ModConfiguration[] | ModInfo[];
}

export enum AdditionalContentType {
	ADDONS,
	DISABLEDCONTENT,
}

class PanelMPAdditionalContent extends Panel {
	private panelOptions: MpAdditionalContentOptions | null = null;

	private titleText!: HTMLElement;
	private descriptionText!: HTMLElement;
	private closeButton!: HTMLElement;
	private slotDiv!: HTMLElement;
	private frame!: HTMLElement;

	private closeButtonListener = this.onClose.bind(this);
	private engineInputListener = this.onEngineInput.bind(this);

	constructor(root: ComponentRoot) {
		super(root);
		this.animateInType = this.animateOutType = AnchorType.RelativeToRight;
	}

	onInitialize() {
		this.titleText = MustGetElement(".font-title", this.Root);
		this.frame = MustGetElement("fxs-modal-frame", this.Root);
		this.descriptionText = MustGetElement(".additional-content-list", this.Root);
		this.closeButton = MustGetElement(".mp-additional-content__close-button", this.Root);
		this.slotDiv = MustGetElement(".additional-content-list", this.Root);
		this.enableOpenSound = true;
		this.enableCloseSound = true;
		this.Root.setAttribute("data-audio-group-ref", "audio-mp-additional-content");
	}

	onAttach() {
		super.onAttach();
		this.Root.addEventListener(InputEngineEventName, this.engineInputListener);
		this.closeButton.addEventListener("action-activate", this.closeButtonListener);

		const closeButton = document.createElement("fxs-close-button");
		closeButton.classList.add("top-1", "right-1");
		closeButton.addEventListener("action-activate", this.closeButtonListener);
		waitForLayout(() => this.frame.appendChild(closeButton)); // need to wait for the button to not be added within the content div
	}

	setPanelOptions(options: object) {
		if (this.panelOptions) {
			return;
		}

		this.panelOptions = options as MpAdditionalContentOptions;
		this.titleText.setAttribute("title", this.panelOptions?.title);

		if (this.panelOptions?.type == AdditionalContentType.ADDONS) {
			(this.panelOptions?.content as ModConfiguration[]).forEach((mod) => {
				this.appendToModalContent(
					Locale.stylize(`[STYLE:text-accent-3][STYLE:font-body-sm]${mod.name}[/S][/S][N]`),
				);
			});
		}

		if (this.panelOptions?.type == AdditionalContentType.DISABLEDCONTENT) {
			(this.panelOptions?.content as ModInfo[]).forEach((mod) => {
				this.appendToModalContent(
					Locale.stylize(`[STYLE:text-accent-3][STYLE:font-body-sm]${mod.name}[/S][/S][N]`),
				);
			});
		}
	}

	appendToModalContent(content: string) {
		const el = document.createElement("div");
		el.innerHTML = content;
		this.descriptionText.appendChild(el);
	}

	onDetach() {
		this.Root.removeEventListener(InputEngineEventName, this.engineInputListener);
		super.onDetach();
	}

	onReceiveFocus() {
		super.onReceiveFocus();
		NavTray.clear();
		FocusManager.get().setFocus(this.slotDiv);
	}

	onLoseFocus() {
		NavTray.clear();
		super.onLoseFocus();
	}

	onClose() {
		this.close();
	}

	private onEngineInput(inputEvent: InputEngineEvent) {
		if (inputEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		if (inputEvent.isCancelInput()) {
			this.onClose();
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
		}
	}
}

Controls.define("screen-mp-additional-content", {
	createInstance: PanelMPAdditionalContent,
	description: "Multiplayer additional content screen.",
	classNames: ["screen-mp-additional-content"],
	styles: [styles],
	innerHTML: [content],
	attributes: [],
});
